//! The shell's local world, generated by the **real** Lodestone worldgen
//! pipeline.
//!
//! Until recently this file was a 189-line sine+hash stand-in. It now calls
//! [`lodestone_server::overworld_generator`], which wraps the version-free,
//! JVM-verified `lodestone-worldgen` pipeline (noise router → interpolated
//! density → sea-level aquifer approximation → surface rules), so the terrain on
//! screen is real vanilla shape+surface for a fixed seed — the same block field
//! `chunk_parity`/`surface_parity` prove bit-for-bit against a JVM.
//!
//! # Why a direct call (and how it stays replaceable)
//!
//! Vanilla singleplayer runs an integrated server that streams chunks to the
//! client over a loopback connection; that is the faithful end state and
//! `lodestone-server` already hosts it (`lodestone_server::IntegratedServer`).
//! This module deliberately takes the *direct* path instead — build the
//! generator once, call [`OverworldGenerator::column`] per chunk — because it
//! closes the island today without waiting on the client's clientbound chunk
//! decode seam. The seam is drawn so the integrated-server path replaces the
//! *call site here*, not the generator: everything below `generate_column` is
//! already the shared code multiplayer uses.
//!
//! # Honest scope of what renders
//!
//! The composed generator produces real terrain **shape + surface** only. It
//! does not yet run carvers (no caves), the full aquifer (no underground
//! water/lava pockets), or features (no ores, trees, or vegetation) — those
//! stages exist and are individually verified, and are the next things to chain
//! in. Generation also runs a single fixed biome (plains) until the multi-noise
//! biome source lands. So this is a real Minecraft *landscape*, not a
//! block-for-block-complete chunk, and it says so.
//!
//! # Vertical windowing
//!
//! The real overworld spans world Y `-64..=319`. The shell renders a window
//! `[MIN_Y, MIN_Y + SECTION_COUNT*16)` of that same world coordinate space
//! (shell Y **is** world Y). Everything below `MIN_Y` is solid stone the player
//! never sees, so dropping it keeps meshing cheap; the bottom row is forced to
//! bedrock for a guaranteed sealed floor.

use std::sync::OnceLock;

use lodestone_server::{OverworldGenerator, overworld_generator};
use lodestone_world::{
    ChunkColumn, ChunkPos, ColumnLight, Heightmaps, LoadedChunk, PaletteKind, World,
};

use crate::blocks::id;

/// Fixed world seed. Chosen so the origin column is pleasant dry grassland
/// (surface ≈ y70) rather than mid-ocean, which seed 42's origin happens to be.
pub const WORLD_SEED: i64 = 3;

/// World vertical layout: lowest rendered block at y=0 (= world y 0).
pub const MIN_Y: i32 = 0;
/// Number of 16-tall sections rendered per column (96 blocks — covers plains
/// surface ≈ y64–90 with headroom).
pub const SECTION_COUNT: usize = 6;
/// Vanilla overworld sea level; non-solid blocks below it are water.
pub const SEA_LEVEL: i32 = 63;

/// Exclusive top of the rendered window in world Y.
const TOP_Y: i32 = MIN_Y + (SECTION_COUNT as i32) * 16;

/// The bundled overworld generator, built once (the density tree + surface
/// noises are seed-dependent and non-trivial to construct, so this is shared
/// across every column and every `surface_height` query).
fn generator() -> &'static OverworldGenerator {
    static GEN: OnceLock<OverworldGenerator> = OnceLock::new();
    GEN.get_or_init(|| overworld_generator(WORLD_SEED))
}

/// Strips any `[properties]` suffix from a block-state string.
fn base(name: &str) -> &str {
    name.split('[').next().unwrap_or(name)
}

/// Maps a vanilla block-state name onto the shell's tiny demo palette. Unknown
/// solid blocks fall back to stone (a safe, always-in-atlas id); this only maps
/// the states the shape+surface pipeline actually emits for plains.
fn map_block(name: &str) -> u32 {
    match base(name) {
        "minecraft:air" | "minecraft:cave_air" | "minecraft:void_air" => id::AIR,
        "minecraft:grass_block" => id::GRASS,
        "minecraft:dirt"
        | "minecraft:coarse_dirt"
        | "minecraft:rooted_dirt"
        | "minecraft:mud"
        | "minecraft:podzol" => id::DIRT,
        "minecraft:sand"
        | "minecraft:red_sand"
        | "minecraft:sandstone"
        | "minecraft:red_sandstone" => id::SAND,
        "minecraft:gravel" => id::GRAVEL,
        "minecraft:water" | "minecraft:lava" => id::WATER,
        "minecraft:bedrock" => id::BEDROCK,
        // stone, deepslate, tuff, calcite, and any other solid: render as stone.
        _ => id::STONE,
    }
}

/// Surface height (world-Y of the highest walkable, i.e. non-air/non-fluid,
/// block) at world column `(wx, wz)`, clamped to the rendered window.
#[must_use]
pub fn surface_height(wx: i32, wz: i32) -> i32 {
    let cx = wx.div_euclid(16);
    let cz = wz.div_euclid(16);
    let lx = wx.rem_euclid(16) as usize;
    let lz = wz.rem_euclid(16) as usize;
    let col = generator().column(cx, cz);
    for y in (MIN_Y..TOP_Y).rev() {
        match base(col.block_state(lx, y, lz)) {
            "minecraft:air" | "minecraft:cave_air" | "minecraft:water" | "minecraft:lava" => {}
            _ => return y,
        }
    }
    MIN_Y
}

/// Generate a single chunk column at chunk position `(cx, cz)` by windowing the
/// real generator's output into the shell's [`ChunkColumn`].
#[must_use]
pub fn generate_column(cx: i32, cz: i32) -> LoadedChunk {
    let col = generator().column(cx, cz);

    let mut column = ChunkColumn::new(
        MIN_Y,
        SECTION_COUNT,
        PaletteKind::block_states(),
        PaletteKind::biomes(),
        id::AIR,
        0,
    );

    for lx in 0..16usize {
        for lz in 0..16usize {
            for y in MIN_Y..TOP_Y {
                let block = if y == MIN_Y {
                    // Guaranteed sealed floor regardless of seed/column.
                    id::BEDROCK
                } else {
                    map_block(col.block_state(lx, y, lz))
                };
                if block != id::AIR {
                    column.set_block(lx, y, lz, block);
                }
            }
        }
    }

    // The shell has no server light for a local world; full sky light is a fine
    // approximation and matches how meshing treats above-ground air.
    let light = ColumnLight::new(SECTION_COUNT);
    let heightmaps = Heightmaps::new();
    LoadedChunk::new(column, light, heightmaps, Vec::new())
}

/// Generate a square patch of chunks of radius `radius` (in chunks) centred on
/// chunk `(0,0)`, loaded into a fresh [`World`].
///
/// Real worldgen is ~100× the cost of the old sine stand-in (measured
/// ≈250 ms/chunk single-threaded in release), so a full `render_distance`
/// patch is generated in parallel across the machine's cores. This is a
/// coarse, per-chunk split over the *same* [`generate_column`] entry point —
/// the seam the integrated-server path will later replace — so nothing about
/// the generator or its determinism changes; only the batch driver fans out.
#[must_use]
pub fn generate(radius: i32) -> World {
    let coords: Vec<(i32, i32)> = (-radius..=radius)
        .flat_map(|cz| (-radius..=radius).map(move |cx| (cx, cz)))
        .collect();

    let workers = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(4)
        .clamp(1, coords.len().max(1));

    let batch = coords.len().div_ceil(workers);
    let mut world = World::new();

    std::thread::scope(|scope| {
        let handles: Vec<_> = coords
            .chunks(batch.max(1))
            .map(|slice| {
                scope.spawn(move || {
                    slice
                        .iter()
                        .map(|&(cx, cz)| (ChunkPos { x: cx, z: cz }, generate_column(cx, cz)))
                        .collect::<Vec<_>>()
                })
            })
            .collect();

        for handle in handles {
            for (pos, chunk) in handle.join().expect("worldgen worker panicked") {
                world.load(pos, chunk);
            }
        }
    });

    world
}

/// A comfortable spawn position (feet) just above the surface at the world
/// origin.
#[must_use]
pub fn spawn_feet() -> [f64; 3] {
    let surface = surface_height(0, 0);
    [0.5, (surface + 1) as f64, 0.5]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn surface_is_deterministic() {
        assert_eq!(surface_height(3, 7), surface_height(3, 7));
    }

    #[test]
    fn bedrock_floor_and_real_surface() {
        let chunk = generate_column(0, 0);
        let col = &chunk.column;
        assert_eq!(
            col.get_block(0, MIN_Y, 0),
            id::BEDROCK,
            "forced bedrock at the floor"
        );
        // Seed 3's origin is dry grassland: the top walkable block is grass and
        // the block above it is air.
        let surface = surface_height(0, 0);
        assert!(
            (SEA_LEVEL..TOP_Y).contains(&surface),
            "origin surface {surface} should be dry land in the window"
        );
        assert_eq!(
            col.get_block(0, surface, 0),
            id::GRASS,
            "origin surface is grass"
        );
        assert_eq!(col.get_block(0, surface + 1, 0), id::AIR);
    }

    #[test]
    fn columns_are_not_all_air() {
        let chunk = generate_column(2, -3);
        let col = &chunk.column;
        let mut solids = 0;
        for y in MIN_Y..TOP_Y {
            if col.get_block(8, y, 8) != id::AIR {
                solids += 1;
            }
        }
        assert!(solids > 20, "expected a solid column, got {solids} solids");
    }

    #[test]
    fn water_appears_below_sea_level_somewhere() {
        // The generator's world has oceans; a small patch around origin should
        // contain some water (the fluid stage ran), even if the origin column is
        // dry. Scan a few chunks.
        let mut water = 0usize;
        for cz in -1..=1 {
            for cx in -1..=1 {
                let chunk = generate_column(cx, cz);
                let col = &chunk.column;
                for y in MIN_Y..=SEA_LEVEL {
                    for lz in 0..16usize {
                        for lx in 0..16usize {
                            if col.get_block(lx, y, lz) == id::WATER {
                                water += 1;
                            }
                        }
                    }
                }
            }
        }
        assert!(water > 0, "fluid stage produced no water in a 3x3 patch");
    }

    #[test]
    fn generate_loads_the_expected_chunk_count() {
        let world = generate(2);
        assert_eq!(world.len(), 25, "5x5 patch");
        assert!(crate::blocks::palette().len() >= 9);
    }
}
